INSERT INTO BUDGET_REVIEW_TASK (
    ID, FILE_NAME, CONTENT_TYPE, FILE_SIZE, TEMP_FILE_PATH, STATUS,
    PARSED_LINE_COUNT, ERROR_DETAIL, BUDGET_YEAR, DEPARTMENT_CODE,
    REVIEW_CURSOR, PENDING_ROW_NUMBER, PENDING_STEP, PENDING_REASON, CREATED_TIME, UPDATED_TIME
) VALUES (
    #{row.id}, #{row.fileName}, #{row.contentType}, #{row.fileSize}, #{row.tempFilePath}, #{row.status},
    #{row.parsedLineCount}, #{row.errorDetail}, #{row.budgetYear}, #{row.departmentCode},
    #{row.reviewCursor}, #{row.pendingRowNumber}, #{row.pendingStep}, #{row.pendingReason},
    #{row.createdTime}, #{row.updatedTime}
)

mapper.select:
SELECT * FROM (SELECT T.*,ROW_NUMBER() OVER (ORDER BY UPDATED_TIME,ID) RN FROM BUDGET_REVIEW_TASK T
WHERE STATUS='FAILED' AND PARSED_LINE_COUNT=0 AND TEMP_FILE_PATH IS NOT NULL
AND ERROR_DETAIL IN ('MATERIAL_CALL_TIMEOUT','MATERIAL_TIME_LIMIT','MATERIAL_QUEUE_TIMEOUT')) WHERE RN <= #{limit}

SELECT ID, FILE_NAME, CONTENT_TYPE, FILE_SIZE, TEMP_FILE_PATH, STATUS, PARSED_LINE_COUNT, ERROR_DETAIL, BUDGET_YEAR, DEPARTMENT_CODE, REVIEW_CURSOR, PENDING_ROW_NUMBER, PENDING_STEP, PENDING_REASON, CREATED_TIME, UPDATED_TIME FROM ( SELECT ID, FILE_NAME, CONTENT_TYPE, FILE_SIZE, TEMP_FILE_PATH, STATUS, PARSED_LINE_COUNT, ERROR_DETAIL, BUDGET_YEAR, DEPARTMENT_CODE, REVIEW_CURSOR, PENDING_ROW_NUMBER, PENDING_STEP, PENDING_REASON, CREATED_TIME, UPDATED_TIME, ROW_NUMBER() OVER (ORDER BY CREATED_TIME DESC, ID DESC) AS RN FROM BUDGET_REVIEW_TASK
AND (ERROR_DETAIL IS NULL OR ERROR_DETAIL NOT IN ('MATERIAL_CALL_TIMEOUT','MATERIAL_TIME_LIMIT','MATERIAL_QUEUE_TIMEOUT')) AND ID = #{batchId} AND BUDGET_YEAR = #{budgetYear} AND DEPARTMENT_CODE = #{departmentCode} AND INSTR(LOWER(FILE_NAME), LOWER(#{fileName})) > 0 AND CREATED_TIME >= #{createdFrom} AND CREATED_TIME < #{createdBefore}
) PAGE_DATA WHERE RN > #{offset} AND RN <= (#{offset} + #{limit}) ORDER BY RN

SELECT COUNT(1)
FROM BUDGET_REVIEW_TASK

    AND (ERROR_DETAIL IS NULL OR ERROR_DETAIL NOT IN ('MATERIAL_CALL_TIMEOUT','MATERIAL_TIME_LIMIT','MATERIAL_QUEUE_TIMEOUT'))
    AND ID = #{batchId}
    AND BUDGET_YEAR = #{budgetYear}
    AND DEPARTMENT_CODE = #{departmentCode}
    AND INSTR(LOWER(FILE_NAME), LOWER(#{fileName})) > 0
    AND CREATED_TIME >= #{createdFrom}
    AND CREATED_TIME < #{createdBefore}
